import React, { useEffect, useState } from "react";
import Slider from "react-slick";

// Import css files
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import AfroStyles from "./afroStyles";

function CarouselQuantityDiscountsSmall({
  quantityDiscounts,
  setopenRequiredQuantityModal,
  setselectedWholesalerReceipt,
}) {
  console.log("qty discounts", quantityDiscounts);
  const [nav1, setNav1] = useState(null);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slider1, setSlider1] = useState(null);
  useEffect(() => {
    setNav1(slider1);
  }, [slider1]);

  const settings = {
    dots: true,
    speed: 1000,
    slidesToShow: 2,
    slidesToScroll: 1,
    infinite: true,
    autoplay: true,
    onReInit: () => setCurrentSlide(slider1?.innerSlider.state.currentSlide),
    autoplaySpeed: 1000,
    lazyLoad: true,
    asNavFor: ".slider-nav",
    focusOnSelect: true,
    nextArrow: (
      <div>
        <div className="next-slick-arrow">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            stroke="black"
            height="24"
            viewBox="0 -960 960 960"
            width="24"
          >
            <path d="m242-200 200-280-200-280h98l200 280-200 280h-98Zm238 0 200-280-200-280h98l200 280-200 280h-98Z" />
          </svg>
        </div>
      </div>
    ),
    prevArrow: (
      <div>
        <div className="next-slick-arrow rotate-180">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            stroke="black"
            height="24"
            viewBox="0 -960 960 960"
            width="24"
          >
            <path d="m242-200 200-280-200-280h98l200 280-200 280h-98Zm238 0 200-280-200-280h98l200 280-200 280h-98Z" />
          </svg>
        </div>
      </div>
    ),
    responsive: [
      {
        breakpoint: 1024,
        settings: {
          slidesToShow: 2,
        },
      },
      {
        breakpoint: 600,
        settings: {
          slidesToShow: 1,
        },
      },
    ],
  };

  return (
    <>
      <div className="content">
        <h1 className="header text-white font-bold">Quantity Discounts</h1>
        <div className="container">
          <Slider
            {...settings}
            asNavFor={nav1}
            ref={(slider) => setSlider1(slider)}
          >
            {quantityDiscounts.map((item) => (
              <div key={item.id}>
                <div className="img-body">
                  <img
                    className="mb-10"
                    style={{ height: 300, width: 250 }}
                    src={
                      item.quantity_discount_banners &&
                      item.quantity_discount_banners.length
                        ? item.quantity_discount_banners[0].thumbnail
                        : ""
                    }
                    alt={item.title}
                  />
                  <p className="my-10 font-semibold text-xl">{item.title}</p>
                </div>
              </div>
            ))}
          </Slider>
          <div style={{ height: 100, width: 75 }} className="thumb-wrapper">
            {quantityDiscounts.map((item, idx) => (
              <div
                key={item.id}
                className={currentSlide === idx ? "active" : null}
                onClick={() => {
                  slider1?.slickGoTo(idx);
                }}
              >
                <img
                  src={
                    item.quantity_discount_banners &&
                    item.quantity_discount_banners.length
                      ? item.quantity_discount_banners[0].thumbnail
                      : ""
                  }
                  alt={item.title}
                />
                {currentSlide}
                <p>{item.title}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </>
  );
}

export default CarouselQuantityDiscountsSmall;
